{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Emodin-8-O-β-D-glucoside, an anthraquinone glycoside sharing the same anthraquinone core as chrysophanol, was detected in rat brain after systemic administration in a dose-dependent manner, directly demonstrating that anthraquinone-based compounds can achieve meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "The anthraquinone-fused heterocycle CC12 was found in mouse cortex, striatum, and CSF after systemic dosing and was classified as passive diffusion, providing direct evidence that the anthraquinone scaffold can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "The quinone TIQ accumulated to high brain concentrations in marmosets after injection, supporting BBB permeation of lipophilic quinone/anthraquinone-like structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Orcinol, a small methylated dihydroxybenzene, was qualitatively detected in mouse brain after systemic administration, supporting CNS access for small phenolic compounds with similar polar functionality.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Although the physicochemical prior is cautious because of the acidic phenolic groups and possible efflux, the strongest transferable experimental evidence comes from anthraquinone and quinone derivatives that clearly penetrate the BBB after systemic administration. Chrysophanol is a lipophilic anthraquinone aglycone, and the direct brain distribution of a more polar anthraquinone glycoside and passive CNS detection of anthraquinone-fused compounds outweigh the uncertain ionization-based prior. Therefore, chrysophanol is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain or plasma pharmacokinetic measurement for chrysophanol itself is available in the provided evidence.",
    "The closest direct anthraquinone evidence is a glycoside, which may involve different transport or metabolism pathways.",
    "The impact of chrysophanol's acidic ionization and possible efflux liability on its net brain exposure is not experimentally resolved."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

